import type { RoleMMRResult, Role } from "@/lib/algorithm/types";
import { rankColor, roleColor, roleLabel, confidenceLabel, divisionLabel } from "@/lib/rank-utils";

interface RoleCardProps {
  role: Role;
  result: RoleMMRResult;
}

export function RoleCard({ role, result }: RoleCardProps) {
  const rColor = roleColor(role);

  if (result.status === "unranked") {
    return (
      <div
        className="rounded-lg p-5 flex flex-col gap-2 opacity-40"
        style={{
          background: "var(--surface-2)",
          border: `1px solid var(--border-subtle)`,
        }}
      >
        <p className="text-xs font-display tracking-widest uppercase" style={{ color: rColor }}>
          {roleLabel(role)}
        </p>
        <p className="text-2xl font-display font-bold opacity-30">—</p>
        <p className="text-xs opacity-50 font-display">Not ranked this season</p>
      </div>
    );
  }

  if (result.status === "insufficient_games") {
    const dLabel = result.division ? `${divisionLabel(result.division)} ${result.tier}` : "—";
    return (
      <div
        className="rounded-lg p-5 flex flex-col gap-2"
        style={{
          background: "var(--surface-2)",
          border: `1px solid ${rColor}22`,
        }}
      >
        <p className="text-xs font-display tracking-widest uppercase" style={{ color: rColor }}>
          {roleLabel(role)}
        </p>
        {result.rankIcon && (
          <img src={result.rankIcon} alt={dLabel} className="w-12 h-12 opacity-60" />
        )}
        <p
          className="text-xs font-display tracking-wide"
          style={{ color: result.division ? rankColor(result.division) : "white" }}
        >
          {dLabel}
        </p>
        <p className="text-lg font-display font-bold opacity-40">{result.mmr.toLocaleString()}</p>
        <p className="text-xs opacity-40 font-display" style={{ color: "var(--orange-accent)" }}>
          Rank-only estimate · Too few games
        </p>
      </div>
    );
  }

  // status === "ranked"
  const dLabel = result.division ? `${divisionLabel(result.division)} ${result.tier}` : "";
  const divColor = result.division ? rankColor(result.division) : "white";
  const conf = confidenceLabel(result.confidence);
  const modifierPositive = (result.modifier ?? 0) > 0;
  const modifierZero = (result.modifier ?? 0) === 0;

  return (
    <div
      className="rounded-lg p-5 flex flex-col gap-3 transition-all duration-200"
      style={{
        background: "var(--surface-2)",
        border: `1px solid ${rColor}33`,
        boxShadow: `0 0 20px ${rColor}0a`,
      }}
    >
      {/* Role label */}
      <p className="text-xs font-display tracking-widest uppercase" style={{ color: rColor }}>
        {roleLabel(role)}
      </p>

      {/* Rank icon + label */}
      <div className="flex items-center gap-3">
        {result.rankIcon && (
          <img src={result.rankIcon} alt={dLabel} className="w-10 h-10 shrink-0" />
        )}
        <p className="text-sm font-display font-semibold tracking-wide" style={{ color: divColor }}>
          {dLabel}
        </p>
      </div>

      {/* MMR number */}
      <div>
        <p
          className="text-4xl font-display font-black leading-none"
          style={{ letterSpacing: "-0.02em", color: "white" }}
        >
          {result.mmr.toLocaleString()}
        </p>
        {/* Modifier */}
        <p
          className="text-sm font-display mt-1 font-semibold"
          style={{
            color: modifierZero
              ? "rgba(255,255,255,0.3)"
              : modifierPositive
              ? "var(--role-support)"
              : "var(--role-damage)",
          }}
        >
          {modifierZero ? "±0" : modifierPositive ? `+${result.modifier}` : result.modifier}
          <span className="text-xs font-normal ml-1 opacity-60">vs rank baseline</span>
        </p>
      </div>

      {/* Confidence + smurf flag */}
      <div className="flex items-center gap-2 flex-wrap">
        <span
          className="text-xs font-display tracking-wide px-2 py-0.5 rounded"
          style={{
            background: `${conf.color}18`,
            color: conf.color,
            border: `1px solid ${conf.color}30`,
          }}
        >
          {conf.label}
        </span>
        {result.reason === "potential_smurf" && (
          <span
            className="text-xs font-display tracking-wide px-2 py-0.5 rounded"
            style={{
              background: "rgba(255,124,42,0.1)",
              color: "var(--orange-accent)",
              border: "1px solid rgba(255,124,42,0.3)",
            }}
          >
            ⚠ New / smurf?
          </span>
        )}
      </div>
    </div>
  );
}
