import { getPlayerSummary, getPlayerStats } from "@/lib/overfast/client";
import { transformPlayerData } from "@/lib/overfast/transform";
import { estimateMMR } from "@/lib/algorithm";
import type { MMREstimate } from "@/lib/algorithm/types";
import type { Platform } from "@/lib/algorithm/types";

export type PlayerPageData =
  | {
      status: "ok";
      username: string;
      avatar: string | null;
      platform: Platform;
      season: number | null;
      competitive: ReturnType<typeof transformPlayerData>["competitive"];
      mmr: MMREstimate;
      statsPartial: boolean;
    }
  | { status: "not_found" }
  | { status: "private"; username: string }
  | { status: "rate_limited" }
  | { status: "error"; message: string };

export async function fetchPlayerData(
  tag: string,
  platform: Platform
): Promise<PlayerPageData> {
  const [summaryResult, statsResult] = await Promise.all([
    getPlayerSummary(tag),
    getPlayerStats(tag, { platform, gamemode: "competitive" }),
  ]);

  if (!summaryResult.ok) {
    const err = summaryResult.error;
    if (err.type === "not_found") return { status: "not_found" };
    if (err.type === "rate_limited") return { status: "rate_limited" };
    return { status: "error", message: `Upstream error: ${err.type}` };
  }

  const statsData = statsResult.ok ? statsResult.data : null;
  const playerData = transformPlayerData(summaryResult.data, statsData, platform);

  if (playerData.isPrivate) {
    return { status: "private", username: playerData.username };
  }

  const mmr = estimateMMR({
    platform: playerData.platform,
    competitive: playerData.competitive,
    stats: playerData.stats,
  });

  return {
    status: "ok",
    username: playerData.username,
    avatar: playerData.avatar,
    platform: playerData.platform,
    season: playerData.season,
    competitive: playerData.competitive,
    mmr,
    statsPartial: !statsResult.ok,
  };
}
