import type { PlayerSummary, PlayerStatsSummary } from "./client";
import type { Role, Platform, RoleStats, CompetitiveDivision } from "@/lib/algorithm/types";

export interface PlayerData {
  username: string;
  avatar: string | null;
  platform: Platform;
  isPrivate: boolean;
  competitive: Partial<Record<Role, { division: CompetitiveDivision; tier: number; rank_icon?: string } | null>>;
  stats: Partial<Record<Role, RoleStats | null>>;
  season: number | null;
}

const ROLES: Role[] = ["tank", "damage", "support"];

export function transformPlayerData(
  summary: PlayerSummary,
  stats: PlayerStatsSummary | null,
  platform: Platform
): PlayerData {
  const platformRanks = summary.competitive?.[platform];

  const competitive: PlayerData["competitive"] = {};
  for (const role of ROLES) {
    const rank = platformRanks?.[role];
    if (rank) {
      competitive[role] = {
        division: rank.division as CompetitiveDivision,
        tier: rank.tier,
        rank_icon: rank.rank_icon,
      };
    } else {
      competitive[role] = null;
    }
  }

  const statsRoles = stats?.roles;
  const playerStats: PlayerData["stats"] = {};
  for (const role of ROLES) {
    const rs = statsRoles?.[role];
    if (!rs) {
      playerStats[role] = null;
      continue;
    }
    playerStats[role] = {
      games_played: rs.games_played,
      games_won: rs.games_won,
      winrate: rs.winrate,
      kda: rs.kda,
      average: {
        deaths: rs.average.deaths,
        damage: rs.average.damage,
        healing: rs.average.healing,
      },
      total: {
        eliminations: rs.total.eliminations,
        assists: rs.total.assists,
        deaths: rs.total.deaths,
        damage: rs.total.damage,
        healing: rs.total.healing,
      },
    } satisfies RoleStats;
  }

  return {
    username: summary.username,
    avatar: summary.avatar ?? null,
    platform,
    isPrivate: !summary.competitive, // null competitive → private or no comp played
    competitive,
    stats: playerStats,
    season: platformRanks?.season ?? null,
  };
}
